CREATE OR REPLACE FUNCTION private.require_available_plan(p_organization_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_subscription public.subscriptions; v_limit integer;
begin
  select * into v_subscription from public.subscriptions where organization_id = p_organization_id;
  if not found then raise exception 'PLAN_UNAVAILABLE'; end if;
  if v_subscription.status = 'trialing' and v_subscription.current_period_end <= now() then
    raise exception 'TRIAL_EXPIRED';
  end if;
  if v_subscription.status not in ('trialing', 'active') or v_subscription.current_period_end <= now() then
    raise exception 'PLAN_INACTIVE';
  end if;
  select member_limit into v_limit from public.plan_catalog where key = v_subscription.plan_key;
  return v_limit;
end;
$function$

CREATE OR REPLACE FUNCTION private.require_role(p_organization_id uuid, p_roles public.organization_role[])
 RETURNS public.organization_role
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_role public.organization_role;
begin
  v_role := private.organization_role(p_organization_id);
  if v_role is null or not (v_role = any(p_roles)) then
    raise exception using errcode = '42501', message = 'FORBIDDEN';
  end if;
  return v_role;
end;
$function$

CREATE OR REPLACE FUNCTION public.accept_invitation(p_token_hash text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_invitation public.organization_invitations; v_org uuid; v_email text; v_limit integer; v_used bigint; v_reserved bigint;
begin
  if auth.uid() is null then raise exception using errcode = '42501', message = 'NOT_AUTHENTICATED'; end if;
  select organization_id into v_org from public.organization_invitations where token_hash = p_token_hash;
  if v_org is null then raise exception 'INVITATION_INVALID'; end if;
  perform 1 from public.organizations where id = v_org and status = 'active' and deleted_at is null for update;
  if not found then raise exception 'INVITATION_INVALID'; end if;
  select * into v_invitation from public.organization_invitations where token_hash = p_token_hash for update;
  if v_invitation.accepted_at is not null or v_invitation.revoked_at is not null or v_invitation.expires_at <= now() then raise exception 'INVITATION_INVALID'; end if;
  -- Read the verified Auth record, not a caller-supplied email or mutable JWT claim.
  select lower(email) into v_email from auth.users where id = auth.uid() and email_confirmed_at is not null;
  if v_email is null or v_email <> v_invitation.email then raise exception 'INVITATION_INVALID'; end if;
  if exists(select 1 from public.organization_members where organization_id = v_org and user_id = auth.uid()) then raise exception 'ALREADY_MEMBER'; end if;
  v_limit := private.require_available_plan(v_org);
  select count(*) into v_used from public.organization_members where organization_id = v_org;
  select count(*) into v_reserved from public.organization_invitations where organization_id = v_org and accepted_at is null and revoked_at is null and expires_at > now() and id <> v_invitation.id;
  if v_used + v_reserved >= v_limit then raise exception 'SEAT_LIMIT'; end if;
  insert into public.organization_members(organization_id,user_id,role,invited_by) values(v_org,auth.uid(),v_invitation.role,v_invitation.created_by);
  update public.organization_invitations set accepted_at = now() where id = v_invitation.id;
  perform private.audit(v_org, 'invitation.accepted', 'invitation', v_invitation.id, jsonb_build_object('role',v_invitation.role));
  return v_org;
end;
$function$

CREATE OR REPLACE FUNCTION public.change_member_role(p_organization_id uuid, p_user_id uuid, p_role public.organization_role)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor_role public.organization_role; v_target_role public.organization_role;
begin
  perform 1 from public.organizations where id = p_organization_id for update;
  v_actor_role := private.require_role(p_organization_id,array['owner','admin']::public.organization_role[]);
  select role into v_target_role from public.organization_members where organization_id = p_organization_id and user_id = p_user_id;
  if v_target_role is null then raise exception 'MEMBER_NOT_FOUND'; end if;
  if v_actor_role <> 'owner' and (v_target_role = 'owner' or p_role = 'owner') then raise exception using errcode = '42501', message = 'OWNERSHIP_OWNER_ONLY'; end if;
  if v_target_role = 'owner' and p_role <> 'owner' and (select count(*) from public.organization_members where organization_id = p_organization_id and role = 'owner') <= 1 then raise exception 'LAST_OWNER'; end if;
  update public.organization_members set role = p_role where organization_id = p_organization_id and user_id = p_user_id;
  perform private.audit(p_organization_id,'member.role_changed','profile',p_user_id,jsonb_build_object('from',v_target_role,'to',p_role));
end;
$function$

CREATE OR REPLACE FUNCTION public.create_organization(p_name text, p_slug text, p_billing_email text, p_timezone text DEFAULT 'UTC'::text, p_default_currency text DEFAULT 'USD'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user uuid := auth.uid(); v_id uuid; v_days integer;
begin
  if v_user is null then raise exception using errcode = '42501', message = 'NOT_AUTHENTICATED'; end if;
  -- Lock the user so concurrent onboarding cannot create multiple trial organizations.
  perform 1 from auth.users where id = v_user and email_confirmed_at is not null for update;
  if not found then raise exception using errcode = '42501', message = 'EMAIL_NOT_VERIFIED'; end if;
  if exists(select 1 from public.organization_members where user_id = v_user and role = 'owner') then
    raise exception 'ORGANIZATION_LIMIT';
  end if;
  if not exists(select 1 from pg_catalog.pg_timezone_names where name = p_timezone) then raise exception 'INVALID_TIMEZONE'; end if;
  select trial_days into v_days from public.plan_catalog where key = 'trial';
  insert into public.organizations(name, slug, billing_email, timezone, default_currency, trial_ends_at)
  values (btrim(p_name), lower(btrim(p_slug)), lower(btrim(p_billing_email)), p_timezone, upper(p_default_currency), now() + make_interval(days => v_days)) returning id into v_id;
  insert into public.organization_members(organization_id, user_id, role) values (v_id, v_user, 'owner');
  insert into public.subscriptions(organization_id, plan_key, status, current_period_start, current_period_end)
  values (v_id, 'trial', 'trialing', now(), now() + make_interval(days => v_days));
  perform private.audit(v_id, 'organization.created', 'organization', v_id);
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_organization_settings(p_organization_id uuid)
 RETURNS TABLE(id uuid, name text, slug text, billing_email text, timezone text, default_currency text, status text, trial_started_at timestamp with time zone, trial_ends_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_role public.organization_role;
begin
  v_role := private.require_role(p_organization_id, array['owner','admin','member','viewer']::public.organization_role[]);
  return query select o.id, o.name, o.slug, case when v_role = 'owner' then o.billing_email else null end,
    o.timezone, o.default_currency, o.status, o.trial_started_at, o.trial_ends_at, o.created_at, o.updated_at
    from public.organizations o where o.id = p_organization_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.invite_member(p_organization_id uuid, p_email text, p_role public.organization_role, p_token_hash text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor_role public.organization_role; v_limit integer; v_used bigint; v_reserved bigint; v_id uuid; v_email text := lower(btrim(p_email));
begin
  -- Every membership mutation locks this same parent row: pending invitations reserve seats.
  perform 1 from public.organizations where id = p_organization_id for update;
  v_actor_role := private.require_role(p_organization_id, array['owner','admin']::public.organization_role[]);
  if p_role = 'owner' and v_actor_role <> 'owner' then raise exception using errcode = '42501', message = 'OWNERSHIP_OWNER_ONLY'; end if;
  v_limit := private.require_available_plan(p_organization_id);
  if exists(select 1 from public.organization_members m join auth.users u on u.id = m.user_id where m.organization_id = p_organization_id and lower(u.email) = v_email) then raise exception 'ALREADY_MEMBER'; end if;
  update public.organization_invitations set revoked_at = now() where organization_id = p_organization_id and accepted_at is null and revoked_at is null and expires_at <= now();
  if exists(select 1 from public.organization_invitations where organization_id = p_organization_id and email = v_email and accepted_at is null and revoked_at is null) then raise exception 'INVITATION_PENDING'; end if;
  select count(*) into v_used from public.organization_members where organization_id = p_organization_id;
  select count(*) into v_reserved from public.organization_invitations where organization_id = p_organization_id and accepted_at is null and revoked_at is null and expires_at > now();
  if v_used + v_reserved >= v_limit then raise exception 'SEAT_LIMIT'; end if;
  insert into public.organization_invitations(organization_id,email,role,token_hash,created_by)
  values(p_organization_id,v_email,p_role,p_token_hash,auth.uid()) returning id into v_id;
  perform private.audit(p_organization_id, 'invitation.created', 'invitation', v_id, jsonb_build_object('role',p_role));
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.list_organization_members(p_organization_id uuid)
 RETURNS TABLE(user_id uuid, role public.organization_role, full_name text, avatar_url text, email text, joined_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_role public.organization_role;
begin
  v_role := private.require_role(p_organization_id, array['owner','admin','member','viewer']::public.organization_role[]);
  return query select m.user_id, m.role, p.full_name, p.avatar_url,
    case when v_role in ('owner','admin') then u.email::text else null end, m.joined_at
  from public.organization_members m join public.profiles p on p.id = m.user_id join auth.users u on u.id = m.user_id
  where m.organization_id = p_organization_id order by m.joined_at, m.user_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.remove_member(p_organization_id uuid, p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor_role public.organization_role; v_target_role public.organization_role;
begin
  perform 1 from public.organizations where id = p_organization_id for update;
  v_actor_role := private.require_role(p_organization_id,array['owner','admin']::public.organization_role[]);
  select role into v_target_role from public.organization_members where organization_id = p_organization_id and user_id = p_user_id;
  if v_target_role is null then raise exception 'MEMBER_NOT_FOUND'; end if;
  if v_actor_role <> 'owner' and v_target_role = 'owner' then raise exception using errcode = '42501', message = 'OWNERSHIP_OWNER_ONLY'; end if;
  if v_target_role = 'owner' and (select count(*) from public.organization_members where organization_id = p_organization_id and role = 'owner') <= 1 then raise exception 'LAST_OWNER'; end if;
  delete from public.organization_members where organization_id = p_organization_id and user_id = p_user_id;
  perform private.audit(p_organization_id,'member.removed','profile',p_user_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.request_organization_data(p_organization_id uuid, p_kind text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid;
begin
  perform 1 from public.organizations where id = p_organization_id for update;
  perform private.require_role(p_organization_id,array['owner']::public.organization_role[]);
  if p_kind not in ('export','delete') or p_kind is null then raise exception 'INVALID_REQUEST_KIND'; end if;
  select id into v_id from public.organization_data_requests where organization_id = p_organization_id and kind = p_kind and status in ('requested','processing');
  if v_id is not null then return v_id; end if;
  insert into public.organization_data_requests(organization_id,requested_by,kind) values(p_organization_id,auth.uid(),p_kind) returning id into v_id;
  perform private.audit(p_organization_id,'organization.' || p_kind || '_requested','data_request',v_id);
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.revoke_invitation(p_invitation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_org uuid; v_actor_role public.organization_role; v_target_role public.organization_role;
begin
  select organization_id into v_org from public.organization_invitations where id = p_invitation_id;
  perform 1 from public.organizations where id = v_org for update;
  v_actor_role := private.require_role(v_org,array['owner','admin']::public.organization_role[]);
  select role into v_target_role from public.organization_invitations where id = p_invitation_id;
  if v_target_role = 'owner' and v_actor_role <> 'owner' then raise exception using errcode = '42501', message = 'OWNERSHIP_OWNER_ONLY'; end if;
  update public.organization_invitations set revoked_at = now() where id = p_invitation_id and accepted_at is null and revoked_at is null;
  if found then perform private.audit(v_org,'invitation.revoked','invitation',p_invitation_id); end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_organization(p_organization_id uuid, p_name text, p_billing_email text DEFAULT NULL::text, p_timezone text DEFAULT 'UTC'::text, p_default_currency text DEFAULT 'USD'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_role public.organization_role;
begin
  perform 1 from public.organizations where id = p_organization_id for update;
  v_role := private.require_role(p_organization_id, array['owner','admin']::public.organization_role[]);
  if v_role <> 'owner' and p_billing_email is not null then raise exception using errcode = '42501', message = 'BILLING_OWNER_ONLY'; end if;
  if not exists(select 1 from pg_catalog.pg_timezone_names where name = p_timezone) then raise exception 'INVALID_TIMEZONE'; end if;
  update public.organizations set name = btrim(p_name), billing_email = coalesce(lower(btrim(p_billing_email)), billing_email),
    timezone = p_timezone, default_currency = upper(p_default_currency) where id = p_organization_id;
  perform private.audit(p_organization_id, 'organization.updated', 'organization', p_organization_id);
end;
$function$

CREATE OR REPLACE FUNCTION private.knowledge_storage_access(p_name text, p_owner text, p_mode text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare parts text[]; b public.brands; s public.knowledge_sources;
begin
  if p_name is null or char_length(p_name)>250 then return false; end if;
  parts := string_to_array(p_name,'/');
  if cardinality(parts)<>4 or parts[3] !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'
    or parts[4] !~ '^[A-Za-z0-9][A-Za-z0-9_.-]{0,149}$' then return false; end if;
  select * into b from public.brands where id::text=parts[2] and organization_id::text=parts[1];
  if not found or private.organization_role(b.organization_id) is null then return false; end if;
  select * into s from public.knowledge_sources where storage_path=p_name and id::text=parts[3] and brand_id=b.id and organization_id=b.organization_id;
  if p_mode='read' then
    return (s.id is not null and s.deleted_at is null)
      or (s.id is null and p_owner=auth.uid()::text and private.organization_role(b.organization_id) in ('owner','admin'));
  end if;
  if private.organization_role(b.organization_id) not in ('owner','admin') then return false; end if;
  if p_mode='delete' then return s.id is not null or p_owner=auth.uid()::text; end if;
  if p_mode='insert' then
    if b.status<>'active' or p_owner is distinct from auth.uid()::text or exists(select 1 from public.knowledge_sources where id::text=parts[3]) then return false; end if;
    perform private.require_available_plan(b.organization_id);
    return true;
  end if;
  return false;
end $function$

CREATE OR REPLACE FUNCTION private.require_brand_capacity(p_organization_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_limit integer;
begin
  perform private.require_available_plan(p_organization_id);
  select c.brand_limit into v_limit from public.subscriptions s join public.plan_catalog c on c.key=s.plan_key where s.organization_id=p_organization_id;
  if (select count(*) from public.brands where organization_id=p_organization_id and status='active') >= v_limit then raise exception 'BRAND_LIMIT'; end if;
end $function$

CREATE OR REPLACE FUNCTION private.validate_brand_profile(p jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare k text; v jsonb; limits integer[];
begin
  if p is null or jsonb_typeof(p) <> 'object' or octet_length(p::text) > 100000 then raise exception 'INVALID_BRAND'; end if;
  for k, limits in select * from (values
    ('name',array[2,100]),('description',array[10,2000]),('value_proposition',array[10,2000]),
    ('target_audience',array[3,1000]),('category',array[2,100]),('disclosure_text',array[10,500])
  ) bounds(field,width) loop
    if jsonb_typeof(p->k) is distinct from 'string' or char_length(btrim(p->>k)) not between limits[1] and limits[2] then raise exception 'INVALID_BRAND'; end if;
  end loop;
  if not private.valid_knowledge_url(p->>'website_url') then raise exception 'INVALID_WEBSITE'; end if;
  foreach k in array array['pricing_url','docs_url','support_url'] loop
    if jsonb_typeof(p->k) is distinct from 'string' or ((p->>k) <> '' and not private.valid_knowledge_url(p->>k)) then raise exception 'INVALID_WEBSITE'; end if;
  end loop;
  if (p->>'tone') is null or (p->>'tone') not in ('Helpful and concise','Technical','Founder voice','Product specialist','Customer-support style','Custom')
    or (p->>'reply_length') is null or (p->>'reply_length') not in ('concise','standard','detailed')
    or (p->>'real_role') is null or (p->>'real_role') not in ('founder','employee','developer advocate','support','contractor','agency','consultant','other')
    or jsonb_typeof(p->'custom_tone') is distinct from 'string' or char_length(p->>'custom_tone') > 500
    or ((p->>'tone') = 'Custom' and char_length(btrim(p->>'custom_tone')) = 0) then raise exception 'INVALID_PERSONA'; end if;
  foreach k in array array['use_cases','avoid_claims','countries','keywords','exclusions'] loop
    if not private.valid_knowledge_list(p->k,30,200) then raise exception 'INVALID_BRAND_LIST'; end if;
  end loop;
  if not private.valid_knowledge_list(p->'allowed_links',20,2048) then raise exception 'INVALID_ALLOWED_LINK'; end if;
  for v in select value from jsonb_array_elements(p->'allowed_links') loop
    if not private.valid_knowledge_url(v #>> '{}') or private.knowledge_host(v #>> '{}') <> private.knowledge_host(p->>'website_url') then raise exception 'INVALID_ALLOWED_LINK'; end if;
  end loop;
  if jsonb_typeof(p->'competitors') is distinct from 'array' or jsonb_array_length(p->'competitors') > 20 then raise exception 'INVALID_COMPETITOR'; end if;
  for v in select value from jsonb_array_elements(p->'competitors') loop
    if jsonb_typeof(v) <> 'object' or jsonb_typeof(v->'name') is distinct from 'string'
      or char_length(btrim(v->>'name')) not between 2 and 100 or not private.valid_knowledge_url(v->>'domain')
      or not private.valid_knowledge_list(v->'aliases',30,200) then raise exception 'INVALID_COMPETITOR'; end if;
  end loop;
end $function$

CREATE OR REPLACE FUNCTION public.add_knowledge_source(p_brand_id uuid, p_id uuid, p_input jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b public.brands; v_type text; v_pages text[]; v_url text; v_storage text; v_filename text; v_mime text; v_object storage.objects;
begin
  select * into b from public.brands where id=p_brand_id;
  if not found then raise exception 'BRAND_NOT_FOUND'; end if;
  perform 1 from public.organizations where id=b.organization_id for update;
  perform private.require_role(b.organization_id,array['owner','admin']::public.organization_role[]);
  perform private.require_available_plan(b.organization_id);
  select * into b from public.brands where id=p_brand_id for update;
  if b.status<>'active' then raise exception 'BRAND_ARCHIVED'; end if;
  if p_id is null or p_input is null or jsonb_typeof(p_input)<>'object' or octet_length(p_input::text)>2100000 then raise exception 'INVALID_SOURCE'; end if;
  if jsonb_typeof(p_input->'name') is distinct from 'string' or char_length(btrim(p_input->>'name')) not between 2 and 150 then raise exception 'INVALID_SOURCE'; end if;
  v_type:=p_input->>'type';
  if v_type is null or v_type not in ('website','webpage','manual','file') then raise exception 'INVALID_SOURCE'; end if;
  if not private.valid_knowledge_list(p_input->'pages',100,2048) then raise exception 'INVALID_SOURCE'; end if;
  select coalesce(array_agg(distinct value),'{}') into v_pages from jsonb_array_elements_text(p_input->'pages');
  if jsonb_typeof(p_input->'text') is distinct from 'string' or char_length(p_input->>'text')>500000 then raise exception 'INVALID_SOURCE'; end if;
  if v_type in ('website','webpage') then
    if cardinality(v_pages)=0 or (v_type='webpage' and cardinality(v_pages)<>1) then raise exception 'INVALID_SOURCE'; end if;
    foreach v_url in array v_pages loop
      if not private.valid_knowledge_url(v_url) or private.knowledge_host(v_url)<>private.knowledge_host(b.website_url) then raise exception 'UNAPPROVED_DOMAIN'; end if;
    end loop;
    perform private.require_knowledge_page_capacity(p_brand_id,cardinality(v_pages));
  elsif cardinality(v_pages)<>0 then raise exception 'INVALID_SOURCE'; end if;
  if v_type='manual' and char_length(btrim(p_input->>'text'))<20 then raise exception 'INVALID_SOURCE'; end if;
  if (select count(*) from public.knowledge_sources where brand_id=p_brand_id and deleted_at is null)>=100 then raise exception 'SOURCE_LIMIT'; end if;
  if v_type='file' then
    v_storage:=p_input->>'storage_path'; v_filename:=p_input->>'filename'; v_mime:=p_input->>'mime_type';
    if v_storage is null or v_filename is null or v_mime is null
      or v_filename !~ '^[A-Za-z0-9][A-Za-z0-9_.-]{0,149}$'
      or v_storage<>b.organization_id::text || '/' || b.id::text || '/' || p_id::text || '/' || v_filename
      or not ((lower(v_filename) like '%.pdf' and v_mime='application/pdf') or (lower(v_filename) like '%.md' and v_mime in ('text/markdown','text/plain')) or (lower(v_filename) like '%.txt' and v_mime='text/plain')) then raise exception 'INVALID_FILE'; end if;
    select * into v_object from storage.objects where bucket_id='knowledge-private' and name=v_storage for update;
    if not found or v_object.owner_id is distinct from auth.uid()::text then raise exception 'FILE_NOT_FOUND'; end if;
    if (v_object.metadata->>'size') is null or (v_object.metadata->>'size') !~ '^[0-9]+$' or (v_object.metadata->>'size')::numeric not between 1 and 10485760 or v_object.metadata->>'mimetype' is distinct from v_mime then raise exception 'INVALID_FILE'; end if;
  end if;
  insert into public.knowledge_sources(id,organization_id,brand_id,name,type,source_url,storage_path,filename,mime_type,manual_text,selected_pages)
    values(p_id,b.organization_id,b.id,btrim(p_input->>'name'),v_type,v_pages[1],v_storage,v_filename,v_mime,case when v_type='manual' then p_input->>'text' end,v_pages);
  insert into public.knowledge_jobs(organization_id,brand_id,source_id,generation,kind) values(b.organization_id,b.id,p_id,1,'ingest');
  perform private.audit(b.organization_id,'knowledge.added','knowledge_source',p_id,jsonb_build_object('type',v_type));
  return p_id;
end $function$

CREATE OR REPLACE FUNCTION public.archive_brand(p_brand_id uuid, p_archived boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_brand public.brands;
begin
  select * into v_brand from public.brands where id=p_brand_id;
  if not found then raise exception 'BRAND_NOT_FOUND'; end if;
  perform 1 from public.organizations where id=v_brand.organization_id for update;
  perform private.require_role(v_brand.organization_id,array['owner','admin']::public.organization_role[]);
  select * into v_brand from public.brands where id=p_brand_id for update;
